import json, re

def transform(text):
    out = {}
    for part in text.strip().split(";"):
        if not part.strip():
            continue
        k, v = [x.strip() for x in part.split("=", 1)]
        if v.lower() in ("true", "false"):
            val = v.lower() == "true"
        elif re.fullmatch(r"-?\d+", v):
            val = int(v)
        elif re.fullmatch(r"-?\d+\.\d+", v):
            val = float(v)
        else:
            val = v
        out[k] = val
    return json.dumps(out, separators=(",", ":"))

