from datetime import date

def transform(text):
    d = json.loads(text)
    asof = date.fromisoformat(d["as_of"])
    out = {}
    for p in d["people"]:
        b = date.fromisoformat(p["birth"])
        age = asof.year - b.year - ((asof.month, asof.day) < (b.month, b.day))
        out[p["name"]] = age
    return json.dumps(dict(sorted(out.items())), separators=(",", ":"))

