def transform(text):
    def parse_duration(s):
        total = 0
        m = re.search(r'(\d+)h', s)
        if m: total += int(m.group(1)) * 3600
        m = re.search(r'(\d+)m', s)
        if m: total += int(m.group(1)) * 60
        m = re.search(r'(\d+)s', s)
        if m: total += int(m.group(1))
        return total
    return '\n'.join(str(parse_duration(line)) for line in text.strip().split('\n'))

