from datetime import datetime

MONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun",
          "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"]

def transform(input):
    out = []
    for line in input.strip("\n").split("\n"):
        s = line.strip()
        iso = "INVALID"
        m = re.fullmatch(r"(\d{1,2})[/-](\d{1,2})[/-](\d{4})", s)
        if m:
            d, mo, y = (int(g) for g in m.groups())
            iso = "%04d-%02d-%02d" % (y, mo, d)
        else:
            m = re.fullmatch(r"(\d{4})-(\d{1,2})-(\d{1,2})", s)
            if m:
                y, mo, d = (int(g) for g in m.groups())
                iso = "%04d-%02d-%02d" % (y, mo, d)
            else:
                m = re.fullmatch(r"([A-Za-z]{3})\s+(\d{1,2})\s+(\d{4})", s)
                if m and m.group(1).title() in MONTHS:
                    mo = MONTHS.index(m.group(1).title()) + 1
                    iso = "%04d-%02d-%02d" % (int(m.group(3)), mo, int(m.group(2)))
        out.append(iso)
    return "\n".join(out)

