def transform(text):
    data = json.loads(text)
    pairs = []

    def walk(node, prefix):
        if isinstance(node, dict):
            for k, v in node.items():
                walk(v, prefix + '.' + k if prefix else k)
        elif isinstance(node, list):
            for i, v in enumerate(node):
                walk(v, prefix + '[' + str(i) + ']')
        else:
            if isinstance(node, bool):
                rendered = 'true' if node else 'false'
            else:
                rendered = str(node)
            pairs.append(prefix + '=' + rendered)

    walk(data, '')
    return '\n'.join(sorted(pairs))

import json, re

LINE = re.compile(r'^(\S+) \S+ \S+ \[[^\]]+\] "(\w+) (\S+) [^"]*" (\d{3}) (\d+)$')

def transform(text):
    stats = {}
    for raw in text.strip().split('\n'):
        m = LINE.match(raw.strip())
        if not m:
            continue
        _, _, path, status, size = m.groups()
        entry = stats.setdefault(path, {'requests': 0, 'errors': 0, 'bytes': 0})
        entry['requests'] += 1
        entry['bytes'] += int(size)
        if int(status) >= 400:
            entry['errors'] += 1
    rows = [
        {
            'path': path,
            'requests': e['requests'],
            'error_rate': round(e['errors'] / e['requests'], 2),
            'bytes': e['bytes'],
        }
        for path, e in stats.items()
    ]
    rows.sort(key=lambda r: (-r['requests'], r['path']))
    return json.dumps(rows)

