            continue
        if '=' in part:
            k, v = part.split('=', 1)
        else:
            k, v = part, ''
        grouped[unquote(k)].append(unquote(v))

    def coerce(v):
        if v.lower() == 'true':
            return True
        if v.lower() == 'false':
            return False
        try:
            if '.' in v:
                return float(v)
            return int(v)
        except ValueError:
            return v

    result = {}
    for k, vals in grouped.items():
