MONTHS = ('January', 'February', 'March', 'April', 'May', 'June', 'July',
          'August', 'September', 'October', 'November', 'December')
DAYS = ('Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday')


def join_list(items):
    if len(items) == 1:
        return items[0]
    return ', '.join(items[:-1]) + ' and ' + items[-1]


def describe_unit(field, singular, plural):
    if field == '*':
        return 'every ' + singular
    if field.startswith('*/'):
        return 'every ' + field[2:] + 'th ' + singular
    parts = field.split(',')
    if len(parts) == 1:
        return singular + ' ' + parts[0]
    return plural + ' ' + join_list(parts)


def transform(text):
    out = []
    for raw in text.split('\n'):
        expression = raw.strip()
        if not expression:
            continue
        fields = expression.split()
        if len(fields) != 5:
            out.append(expression + ' => ERROR: expected 5 fields')
            continue
        minute, hour, dom, month, dow = fields
        parts = [describe_unit(minute, 'minute', 'minutes'),
                 describe_unit(hour, 'hour', 'hours')]
        parts.append('every day of the month' if dom == '*' else 'day-of-month ' + dom)
        parts.append('every month' if month == '*' else MONTHS[int(month) - 1])
        if dow == '*':
            parts.append('every day of the week')
        elif '-' in dow:
            start, end = dow.split('-')
            parts.append(DAYS[int(start)] + ' through ' + DAYS[int(end)])
        else:
            parts.append(DAYS[int(dow)])
        out.append(expression + ' => ' + ', '.join(parts))
    return '\n'.join(out)

