def transform(text):
    files = []
    minus_path = None
    current = None
    for line in text.split('\n'):
        if line.startswith('\\'):
            continue
        if line.startswith('--- '):
            minus_path = line[4:].strip()
            current = None
            continue
        if line.startswith('+++ '):
            plus_path = line[4:].strip()
            if plus_path == '/dev/null':
                path = minus_path[2:] if minus_path.startswith('a/') else minus_path
            else:
                path = plus_path[2:] if plus_path.startswith('b/') else plus_path
            current = {'path': path, 'added': 0, 'removed': 0}
            files.append(current)
            continue
        if line.startswith('@@'):
            continue
        if current is None:
            continue
        if line.startswith('+'):
            current['added'] += 1
        elif line.startswith('-'):
            current['removed'] += 1
    out = []
    total_added = 0
    total_removed = 0
    for entry in files:
        changed = entry['added'] + entry['removed']
        marks = '+' * entry['added'] + '-' * entry['removed']
        out.append('{} | {} {}'.format(entry['path'], changed, marks))
        total_added += entry['added']
        total_removed += entry['removed']

    def plural(count, word):
        return '{} {}{}'.format(count, word, '' if count == 1 else 's')

    out.append('{} changed, {}(+), {}(-)'.format(
        plural(len(files), 'file'),
        plural(total_added, 'insertion'),
        plural(total_removed, 'deletion')))
    return '\n'.join(out)

def transform(text):
    def to_minutes(hhmm):
        hours, minutes = hhmm.split(':')
        return int(hours) * 60 + int(minutes)

    def to_clock(total):
        return '{:02d}:{:02d}'.format(total // 60, total % 60)

    intervals = []
    for line in text.split('\n'):
        line = line.strip()
        if not line:
            continue
        start_text, end_text = line.split('-')
        start = to_minutes(start_text)
        end = to_minutes(end_text)
        if end <= start:
            continue
        intervals.append((start, end))
    intervals.sort()
    merged = []
    for start, end in intervals:
        if merged and start <= merged[-1][1]:
            if end > merged[-1][1]:
                merged[-1][1] = end
        else:
            merged.append([start, end])
    lines = [to_clock(s) + '-' + to_clock(e) for s, e in merged]
    lines.append('total=' + str(sum(e - s for s, e in merged)))
    return '\n'.join(lines)

PAIRS = (
    (1000, 'M'), (900, 'CM'), (500, 'D'), (400, 'CD'),
    (100, 'C'), (90, 'XC'), (50, 'L'), (40, 'XL'),
    (10, 'X'), (9, 'IX'), (5, 'V'), (4, 'IV'), (1, 'I'),
)
DIGITS = {'M': 1000, 'D': 500, 'C': 100, 'L': 50, 'X': 10, 'V': 5, 'I': 1}


def to_roman(number):
    out = []
    remaining = number
    for value, symbol in PAIRS:
        while remaining >= value:
            out.append(symbol)
            remaining -= value
    return ''.join(out)


def transform(text):
    lines = []
    for raw in text.split('\n'):
        token = raw.strip()
        if not token:
            continue
        if token.isdigit():
            number = int(token)
            result = to_roman(number) if 1 <= number <= 3999 else 'ERROR'
        elif all(ch in DIGITS for ch in token):
            total = 0
            for index, ch in enumerate(token):
                value = DIGITS[ch]
                nxt = DIGITS[token[index + 1]] if index + 1 < len(token) else 0
                total += -value if value < nxt else value
            result = str(total) if to_roman(total) == token else 'ERROR'
        else:
            result = 'ERROR'
        lines.append(token + ' -> ' + result)
    return '\n'.join(lines)

