        else:
            ids = []
            for ident in pre.split('.'):
                if ident.isdigit():
                    ids.append((0, int(ident), ''))
                else:
                    ids.append((1, 0, ident))
            pre_key = (0, tuple(ids))
        return (major, minor, patch, pre_key)

    versions = []
    for line in text.split('\n'):
