def transform(text):
    lines = text.split('\n')
    if lines and lines[-1] == '':
        lines = lines[:-1]
    header = lines[0]
    shift = int(header.split(':', 1)[1].strip()) % 26
    out = []
    for line in lines[1:]:
        chars = []
        for ch in line:
            if 'a' <= ch <= 'z':
                chars.append(chr((ord(ch) - 97 + shift) % 26 + 97))
            elif 'A' <= ch <= 'Z':
                chars.append(chr((ord(ch) - 65 + shift) % 26 + 65))
            else:
                chars.append(ch)
        out.append(''.join(chars))
    return '\n'.join(out)

import urllib.parse

SMALL_WORDS = ('and', 'of', 'the', 'in')
SUFFIXES = ('.html', '.htm', '.php')


def render_segment(segment):
    for suffix in SUFFIXES:
        if segment.endswith(suffix):
            segment = segment[:-len(suffix)]
            break
    words = [w for w in segment.replace('-', ' ').replace('_', ' ').split(' ') if w]
    rendered = []
    for index, word in enumerate(words):
        if index > 0 and word.lower() in SMALL_WORDS:
            rendered.append(word.lower())
        else:
            rendered.append(word[:1].upper() + word[1:])
    return ' '.join(rendered)


def transform(text):
    out = []
    for raw in text.split('\n'):
        line = raw.strip()
        if not line:
            continue
        line = line.split('#', 1)[0]
        line = line.split('?', 1)[0]
        marker = line.find('://')
        if marker != -1:
            slash = line.find('/', marker + 3)
            line = line[slash:] if slash != -1 else ''
        path = urllib.parse.unquote(line, encoding='utf-8')
        segments = [s for s in path.split('/') if s]
        crumbs = ['Home'] + [render_segment(s) for s in segments]
        out.append(' > '.join(c for c in crumbs if c))
    return '\n'.join(out)

import re

KEY_RE = re.compile(r'^[A-Za-z_][A-Za-z0-9_]*$')
REF_RE = re.compile(r'\$\{([A-Za-z_][A-Za-z0-9_]*)\}')


def transform(text):
    values = {}
    interpolating = {}
    ignored = 0
    for raw in text.split('\n'):
        line = raw.strip()
        if not line or line.startswith('#'):
            continue
        if line.startswith('export '):
            line = line[len('export '):].strip()
        if '=' not in line:
            ignored += 1
            continue
        key, value = line.split('=', 1)
        key = key.strip()
        if not KEY_RE.match(key):
            ignored += 1
            continue
        value = value.strip()
        expand = True
        if len(value) >= 2 and value[0] == '"' and value[-1] == '"':
            value = value[1:-1]
        elif len(value) >= 2 and value[0] == "'" and value[-1] == "'":
            value = value[1:-1]
            expand = False
        values[key] = value
        interpolating[key] = expand
    for _ in range(10):
        for key in list(values):
            if not interpolating[key]:
                continue
            values[key] = REF_RE.sub(lambda m: values.get(m.group(1), ''), values[key])
    out = [k + '=' + values[k] for k in sorted(values)]
    out.append('ignored=' + str(ignored))
    return '\n'.join(out)

def transform(text):
