            values[name].append(value)
    lines = []
    for name in sorted(values):
        joined = ', '.join(values[name])
        lines.append(name + ': ' + joined if joined else name + ':')
    return '\n'.join(lines)

def transform(text):
    lines = [l for l in text.split('\n') if l.strip()]
    cc = lines[0].split('=', 1)[1].strip()
    out = []
    for raw in lines[1:]:
        body = raw
        for marker in ('x', 'X'):
            position = body.find(marker)
            if position != -1:
                body = body[:position]
        plus = body.lstrip().startswith('+')
        digits = ''.join(ch for ch in body if ch.isdigit())
        if plus:
            national = digits
        elif digits.startswith('00'):
            national = digits[2:]
        elif digits.startswith('0'):
            national = cc + digits[1:]
        else:
            national = cc + digits
        if 8 <= len(national) <= 15:
            out.append('+' + national)
        else:
            out.append('INVALID')
    return '\n'.join(out)

def transform(text):
    lines = [l for l in text.split('\n') if l.strip()]
    rows, cols = (int(p) for p in lines[0].split())
    grid = [[0] * cols for _ in range(rows)]
    for line in lines[1:]:
        row, col, value = (int(p) for p in line.split())
        if 0 <= row < rows and 0 <= col < cols:
            grid[row][col] = value
    rendered = [[str(v) for v in row] for row in grid]
    width = 0
    for row in rendered:
        for cell in row:
            if len(cell) > width:
                width = len(cell)
    return '\n'.join(' '.join(cell.rjust(width) for cell in row) for row in rendered)

import re

PLACEHOLDER = re.compile(r'\{\{([^{}]*)\}\}')


def transform(text):
    lines = text.split('\n')
    if lines and lines[-1] == '':
        lines = lines[:-1]
    separator = lines.index('---')
    table = {}
    for line in lines[:separator]:
        if '=' not in line:
            continue
        key, value = line.split('=', 1)
        table[key.strip()] = value

    def replace(match):
        body = match.group(1)
        if '|' in body:
            name, default = body.split('|', 1)
            default = default.strip()
        else:
            name, default = body, ''
        name = name.strip()
        if name in table:
            return table[name]
        return default

    rendered = [PLACEHOLDER.sub(replace, line).rstrip() for line in lines[separator + 1:]]
    return '\n'.join(rendered)

