import io


def transform(text):
    lines = text.split('\n')
    if lines and lines[-1] == '':
        lines = lines[:-1]
    separator = lines.index('---')
    mapping = []
    for line in lines[:separator]:
        if '->' not in line:
            continue
        source, target = line.split('->', 1)
        mapping.append((source.strip(), target.strip()))
    rows = list(csv.reader(lines[separator + 1:]))
    header = rows[0]
    index_of = {}
    for position, name in enumerate(header):
        if name not in index_of:
            index_of[name] = position
    out = io.StringIO()
    writer = csv.writer(out, lineterminator='\n', quoting=csv.QUOTE_MINIMAL)
    writer.writerow([target for _, target in mapping])
    for row in rows[1:]:
        record = []
        for source, _ in mapping:
            position = index_of.get(source)
            if position is None or position >= len(row):
                record.append('')
            else:
                record.append(row[position])
        writer.writerow(record)
    return out.getvalue().rstrip('\n')

def transform(text):
    out = []
    for raw in text.split('\n'):
        line = raw.strip()
        if not line:
            continue
        digits = line.replace(' ', '').replace('-', '')
        if not digits.isdigit() or not digits.isascii():
            out.append(line + ': INVALID_CHARS')
            continue
        if len(digits) < 13 or len(digits) > 19:
            out.append(line + ': INVALID_LENGTH')
            continue
        total = 0
        for position, ch in enumerate(reversed(digits)):
            value = int(ch)
            if position % 2 == 1:
                value *= 2
                if value > 9:
                    value -= 9
            total += value
        status = 'VALID' if total % 10 == 0 else 'FAILED_CHECKSUM'
        masked = '*' * (len(digits) - 4) + digits[-4:]
        out.append(masked + ': ' + status)
    return '\n'.join(out)

import json


def to_scalar(raw):
    value = raw
    if not value.startswith('"') and not value.startswith("'"):
        position = value.find(' #')
        if position != -1:
            value = value[:position]
    value = value.strip()
    if len(value) >= 2 and ((value[0] == '"' and value[-1] == '"') or (value[0] == "'" and value[-1] == "'")):
        return value[1:-1]
    if value == 'true':
        return True
    if value == 'false':
        return False
    if value in ('null', '~'):
        return None
    body = value[1:] if value.startswith('-') else value
    if body.isdigit() and body.isascii():
        return int(value)
    try:
        return float(value)
    except ValueError:
        return value


def parse_block(entries, index, indent):
    if entries[index][1].startswith('- '):
        items = []
        while index < len(entries) and entries[index][0] == indent and entries[index][1].startswith('- '):
            items.append(to_scalar(entries[index][1][2:]))
            index += 1
        return items, index
    mapping = {}
    while index < len(entries) and entries[index][0] == indent:
        content = entries[index][1]
        key, _, rest = content.partition(':')
        key = key.strip()
        if rest.strip() == '':
            child, index = parse_block(entries, index + 1, indent + 2)
            mapping[key] = child
        else:
            mapping[key] = to_scalar(rest.strip())
            index += 1
    return mapping, index


