def transform(text):
    children = {}
    seen_child = set()
    nodes = set()
    for line in text.strip().split('\n'):
        if not line.strip():
            continue
        parent, child = line.strip().split('>')
        children.setdefault(parent, []).append(child)
        seen_child.add(child)
        nodes.add(parent)
        nodes.add(child)
    out = []
    def emit(node, depth):
        out.append('  ' * depth + node)
        for kid in sorted(children.get(node, [])):
            emit(kid, depth + 1)
    for root in sorted(nodes - seen_child):
        emit(root, 0)
    return '\n'.join(out)

