from collections import defaultdict

def transform(text):
    pairs = json.loads(text)
    children = defaultdict(list)
    all_nodes = set()
    child_nodes = set()
    for p in pairs:
        children[p["parent"]].append(p["child"])
        all_nodes.add(p["parent"])
        all_nodes.add(p["child"])
        child_nodes.add(p["child"])
    roots = sorted(all_nodes - child_nodes)

    depth = {}
    def assign_depth(node, d):
        depth[node] = d
        for c in sorted(children.get(node, [])):
            assign_depth(c, d + 1)

    for r in roots:
        assign_depth(r, 0)

    result = [{"node": n, "depth": depth[n]} for n in sorted(depth)]
    return json.dumps(result)

