from datetime import datetime, timedelta

def transform(text):
    records = json.loads(text)
    # bucket timestamps into hourly buckets, average the value in each bucket
    buckets = {}
    for r in records:
        ts = datetime.fromisoformat(r["ts"].replace("Z", "+00:00"))
        bucket_key = ts.strftime("%Y-%m-%dT%H:00:00Z")
        buckets.setdefault(bucket_key, []).append(r["value"])

    if not buckets:
        return json.dumps([])

    sorted_keys = sorted(buckets.keys())
    start = datetime.fromisoformat(sorted_keys[0].replace("Z", "+00:00"))
    end = datetime.fromisoformat(sorted_keys[-1].replace("Z", "+00:00"))

    result = []
    last_avg = None
    cur = start
    while cur <= end:
        key = cur.strftime("%Y-%m-%dT%H:00:00Z")
        if key in buckets:
            vals = buckets[key]
            avg = round(sum(vals) / len(vals), 2)
            last_avg = avg
            filled = False
        else:
            avg = last_avg
            filled = True
        result.append({"hour": key, "avg_value": avg, "filled": filled})
        cur += timedelta(hours=1)
    return json.dumps(result)

