def transform(text):
    tree = json.loads(text)

    def rollup(node):
        if "children" not in node or not node["children"]:
            node["total"] = node.get("value", 0)
            return node["total"]
        total = node.get("value", 0)
        for child in node["children"]:
            total += rollup(child)
        node["total"] = total
        return total

    rollup(tree)
    return json.dumps(tree)

import json, re

def transform(text):
    payload = json.loads(text)
    template = payload["template"]
    data = payload["data"]

    pattern = re.compile(r"\{\{\s*([\w.]+)\s*(?:\|\s*([^}]*?)\s*)?\}\}")

    def resolve(path):
        cur = data
        for part in path.split("."):
            if isinstance(cur, dict) and part in cur and cur[part] not in (None, ""):
                cur = cur[part]
            else:
                return None
        return cur

    def repl(m):
        path = m.group(1)
        default = m.group(2)
        val = resolve(path)
        if val is None:
            return default if default is not None else ""
        return str(val)

    return pattern.sub(repl, template)

