import json

def transform(text):
    payload = json.loads(text)
    schema = payload["schema"]  # field -> type ("int","float","bool","str")
    records = payload["records"]

    def coerce(value, typ):
        if value is None:
            return None, False
        try:
            if typ == "int":
                return int(str(value).strip()), True
            if typ == "float":
                return float(str(value).strip()), True
            if typ == "bool":
                s = str(value).strip().lower()
                if s in ("true", "1", "yes"):
                    return True, True
                if s in ("false", "0", "no"):
                    return False, True
                return value, False
            if typ == "str":
                return str(value), True
        except (ValueError, TypeError):
            return value, False
        return value, False

    out = []
    for rec in records:
        coerced = {}
        errors = []
        for field, typ in schema.items():
            if field not in rec:
                errors.append(f"missing:{field}")
                continue
            val, ok = coerce(rec[field], typ)
            coerced[field] = val
            if not ok:
                errors.append(f"invalid:{field}")
        out.append({"record": coerced, "valid": len(errors) == 0, "errors": errors})
    return json.dumps(out)

