from datetime import date

def transform(text):
    data = json.loads(text)
    users = data["users"]

    cohorts = {}
    for u in users:
        signup = u["signup_date"]
        cohorts.setdefault(signup, {"users": [], "count": 0})
        cohorts[signup]["users"].append(u)
        cohorts[signup]["count"] += 1

    def week_offset(signup_str, activity_str):
        sy, sm, sd = map(int, signup_str.split("-"))
        ay, am, ad = map(int, activity_str.split("-"))
        delta = (date(ay, am, ad) - date(sy, sm, sd)).days
        return delta // 7

    result = []
    for signup, group in sorted(cohorts.items()):
        total = group["count"]
        week_counts = {}
        for u in group["users"]:
            weeks_active = {week_offset(signup, a) for a in u["active_dates"]}
            for w in weeks_active:
                week_counts[w] = week_counts.get(w, 0) + 1
        max_week = max(week_counts.keys(), default=0)
        retention = []
        for w in range(max_week + 1):
            active = week_counts.get(w, 0)
            retention.append({"week": w, "active_users": active, "retention_pct": round(active / total * 100, 1)})
        result.append({"cohort": signup, "cohort_size": total, "retention": retention})

    return json.dumps(result)

