    return json.dumps(result)

def transform(text):
    tokens = []
    buf = []
    in_quotes = False
    in_comment = False

    def flush():
        if buf:
            tokens.append(''.join(buf))
            del buf[:]

    for ch in text:
        if in_comment:
            if ch == '\n':
                in_comment = False
            continue
        if in_quotes:
            buf.append(ch)
            if ch == '"':
                in_quotes = False
            continue
        if ch == '#':
            in_comment = True
            continue
        if ch == '"':
            buf.append(ch)
            in_quotes = True
            continue
        if ch in '{};':
            flush()
            tokens.append(ch)
            continue
        if ch.isspace():
            flush()
            continue
        buf.append(ch)
    flush()

    stack = []
    pending = []
    lines = []
    for tok in tokens:
        if tok == ';':
            if pending:
                name = pending[0]
                args = pending[1:]
                path = '/'.join(stack + [name])
                arg_text = ' '.join(args) if args else '(none)'
                lines.append('%s = %s' % (path, arg_text))
            pending = []
        elif tok == '{':
            if len(pending) == 1:
                label = pending[0]
            elif pending:
                label = pending[0] + '[' + ' '.join(pending[1:]) + ']'
            else:
                label = '(anon)'
            stack.append(label)
            pending = []
