def _parse_segment(segment):
    coefficient = 1
    i = 0
    while i < len(segment) and segment[i].isdigit():
        i += 1
    if i:
        coefficient = int(segment[:i])
        segment = segment[i:]
    stack = [{}]
    pos = 0
