        match = TOKEN.match(segment, pos)
        if not match or match.end() == pos:
            pos += 1
            continue
        pos = match.end()
        symbol, mult, opening, closing, close_mult = match.groups()
        if symbol:
            count = int(mult) if mult else 1
            top = stack[-1]
            top[symbol] = top.get(symbol, 0) + count
        elif opening:
            stack.append({})
        elif closing:
            group = stack.pop()
            factor = int(close_mult) if close_mult else 1
            top = stack[-1]
            for element, count in group.items():
                top[element] = top.get(element, 0) + count * factor
    while len(stack) > 1:
        group = stack.pop()
        top = stack[-1]
        for element, count in group.items():
