import re

UUID_RE = re.compile(r'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$')
NIL = '00000000-0000-0000-0000-000000000000'
GROUP_ORDER = ['v1', 'v2', 'v3', 'v4', 'v5', 'v6', 'v7', 'v8',
               'nil', 'non-rfc', 'unknown', 'invalid']


def _normalise(token):
    value = token.strip()
    if value.lower().startswith('urn:uuid:'):
        value = value[9:]
    if value.startswith('{') and value.endswith('}') and len(value) >= 2:
        value = value[1:-1]
    return value.lower()


def transform(text):
    groups = {name: [] for name in GROUP_ORDER}
    seen = set()
    for raw in text.split('\n'):
        original = raw.strip()
        if not original:
            continue
        candidate = _normalise(original)
        if not UUID_RE.match(candidate):
            if original in seen:
                continue
            seen.add(original)
            groups['invalid'].append(original)
            continue
        if candidate in seen:
            continue
        seen.add(candidate)
        if candidate == NIL:
            groups['nil'].append(candidate)
            continue
        variant_digit = candidate.split('-')[3][0]
        if variant_digit not in '89ab':
            groups['non-rfc'].append(candidate)
            continue
        version_digit = candidate.split('-')[2][0]
        name = 'v' + version_digit if version_digit in '12345678' else 'unknown'
        groups[name].append(candidate)

    lines = []
    for name in GROUP_ORDER:
        members = groups[name]
        if not members:
            continue
        lines.append('%s: %d -> %s' % (name, len(members), ', '.join(members)))
    return '\n'.join(lines)

def _parse(line):
    if line.count('/') != 1:
        return None
    address, prefix_text = line.split('/')
    if not prefix_text.isdigit():
        return None
    prefix = int(prefix_text)
    if prefix > 32:
        return None
    parts = address.split('.')
    if len(parts) != 4:
        return None
    value = 0
    for part in parts:
        if not part.isdigit():
            return None
        octet = int(part)
        if octet > 255:
            return None
        value = (value << 8) | octet
    return value, prefix


def _dotted(value):
    return '%d.%d.%d.%d' % ((value >> 24) & 255, (value >> 16) & 255,
                            (value >> 8) & 255, value & 255)


def transform(text):
    valid = []
    seen = set()
    invalid = []
    for raw in text.split('\n'):
        line = raw.strip()
        if not line:
            continue
        parsed = _parse(line)
        if parsed is None:
            invalid.append(line)
            continue
        value, prefix = parsed
        mask = 0 if prefix == 0 else ((1 << 32) - 1) ^ ((1 << (32 - prefix)) - 1)
        network = value & mask
        broadcast = network | (((1 << 32) - 1) ^ mask)
        key = (network, prefix)
        if key in seen:
            continue
        seen.add(key)
        total = 1 << (32 - prefix)
        if prefix == 32:
            usable = 1
        elif prefix == 31:
            usable = 2
        else:
            usable = total - 2
        valid.append((network, prefix, broadcast, total, usable))

    valid.sort(key=lambda entry: (entry[0], entry[1]))

    lines = []
    for network, prefix, broadcast, total, usable in valid:
        lines.append('%s/%d %s-%s total=%d usable=%d'
                     % (_dotted(network), prefix, _dotted(network),
                        _dotted(broadcast), total, usable))
    for line in invalid:
        lines.append('INVALID %s' % line)
    return '\n'.join(lines)

import re

MOVE_NUMBER = re.compile(r'^\d+\.+$')
NAG = re.compile(r'^\$\d+$')
RESULTS = ('1-0', '0-1', '1/2-1/2', '*')
SUFFIXES = ('!!', '??', '!?', '?!', '!', '?')


def _strip_braces(text):
    out = []
    depth = 0
    for ch in text:
        if ch == '{':
            depth += 1
            continue
        if ch == '}':
            if depth:
                depth -= 1
            continue
        if depth == 0:
            out.append(ch)
    return ''.join(out)


def _strip_variations(text):
    out = []
    depth = 0
    for ch in text:
        if ch == '(':
            depth += 1
            continue
        if ch == ')':
            if depth:
                depth -= 1
            continue
        if depth == 0:
            out.append(ch)
    return ''.join(out)


def transform(text):
    body_lines = [line for line in text.split('\n') if not line.strip().startswith('[')]
    body = ' '.join(body_lines)
    body = _strip_variations(_strip_braces(body))

    plies = []
    result = 'unknown'
    for token in body.split():
        if MOVE_NUMBER.match(token) or NAG.match(token):
            continue
        if token in RESULTS:
            result = token
            continue
        move = token
        annotation = ''
        for suffix in SUFFIXES:
            if move.endswith(suffix) and len(move) > len(suffix):
                annotation = suffix
                move = move[:-len(suffix)]
                break
        plies.append((move, annotation))

    lines = []
    for number, (move, annotation) in enumerate(plies, start=1):
        color = 'W' if number % 2 == 1 else 'B'
        extra = ' [%s]' % annotation if annotation else ''
        lines.append('%d. %s %s%s' % (number, color, move, extra))
    total = len(plies)
    lines.append('plies=%d moves=%d result=%s' % (total, (total + 1) // 2, result))
    return '\n'.join(lines)

