            if ch == '\\' and i + 1 < len(value):
                nxt = value[i + 1]
                if nxt == ',':
                    out.append(',')
                    i += 2
                    continue
                if nxt == ';':
                    out.append(';')
                    i += 2
                    continue
                if nxt in ('n', 'N'):
                    out.append(' ')
                    i += 2
                    continue
            out.append(ch)
            i += 1
        return ''.join(out)

    def parse_stamp(value):
        return datetime.datetime(
            int(value[0:4]), int(value[4:6]), int(value[6:8]),
