import re

LINE = re.compile(r'^( *)- +(.*)$')


def transform(text):
    roots = []
    # stack of (indent, node); node is None for the synthetic root container
    stack = [(-1, None)]
    for raw in text.split('\n'):
        if not raw.strip():
            continue
        match = LINE.match(raw.rstrip())
        if not match:
            continue
        indent = len(match.group(1))
        name = match.group(2).strip()
        while len(stack) > 1 and stack[-1][0] >= indent:
            stack.pop()
        node = {'name': name, 'children': []}
        parent = stack[-1][1]
        if parent is None:
            roots.append(node)
        else:
            parent['children'].append(node)
        stack.append((indent, node))
    return json.dumps(roots, indent=2, ensure_ascii=True)

