        if key not in cookies:
            order.append(key)
        cookies[key] = (cookie_value.strip(), attrs, domain, path)

    lines = []
    for key in sorted(cookies):
        cookie_value, attrs, domain, path = cookies[key]
        decoded = unquote(cookie_value)
        if decoded == '':
            decoded = '(empty)'
        flags = [f for f in ('Secure', 'HttpOnly') if f in attrs]
        flag_text = '+'.join(flags) if flags else '-'
        samesite = attrs.get('SameSite')
        samesite_text = SAMESITE.get(samesite.strip().lower(), samesite) if samesite else '-'
        max_age = attrs.get('Max-Age')
        max_age_text = str(int(max_age)) if max_age not in (None, '') else '-'
        expires = attrs.get('Expires')
        expires_text = expires if expires else '-'
        lines.append(
            '%s | %s | domain=%s | path=%s | flags=%s | samesite=%s | max-age=%s | expires=%s'
            % (key[0], decoded, domain, path, flag_text, samesite_text,
               max_age_text, expires_text))
    return '\n'.join(lines)

MAJOR_CATS = {'removed', 'breaking'}
MINOR_CATS = {'added', 'changed', 'deprecated'}
PATCH_CATS = {'fixed', 'security', 'performance'}


def transform(text):
    blocks = []
    current = []
    for raw in text.split('\n'):
        line = raw.strip()
        if line == '---':
            blocks.append(current)
            current = []
            continue
        if line:
            current.append(line)
    blocks.append(current)

    releases = []
    index = 0
    while index < len(blocks):
        block = blocks[index]
        if block and block[0].lower().startswith('current:'):
            version = block[0].split(':', 1)[1].strip()
            changes = blocks[index + 1] if index + 1 < len(blocks) else []
            releases.append((version, changes))
            index += 2
            continue
        index += 1

    lines = []
    for version, changes in releases:
        level = 0
        for change in changes:
            if ':' not in change:
                continue
            category = change.split(':', 1)[0].strip().lower()
            if category in MAJOR_CATS:
                level = max(level, 3)
            elif category in MINOR_CATS:
                level = max(level, 2)
            elif category in PATCH_CATS:
                level = max(level, 1)
        if level == 0:
            lines.append('%s -> %s (none)' % (version, version))
            continue
        core = version.split('+', 1)[0].split('-', 1)[0]
        parts = core.split('.')
        major, minor, patch = int(parts[0]), int(parts[1]), int(parts[2])
        if level == 3:
            if major == 0:
                minor += 1
                patch = 0
                label = 'minor(major-demoted)'
            else:
                major += 1
                minor = 0
                patch = 0
                label = 'major'
        elif level == 2:
            minor += 1
            patch = 0
            label = 'minor'
        else:
            patch += 1
            label = 'patch'
        nxt = '%d.%d.%d' % (major, minor, patch)
        lines.append('%s -> %s (%s)' % (version, nxt, label))
    return '\n'.join(lines)

def transform(text):
    rows = []
    for line in text.strip().split('\n')[1:]:
        if not line.strip():
            continue
        name, dept, salary = [p.strip() for p in line.split(',')]
        rows.append((dept, name, int(salary)))
    groups = {}
    for dept, name, salary in rows:
        groups.setdefault(dept, []).append((name, salary))
    out = []
    for dept in sorted(groups):
        members = groups[dept]
        total = sum(s for _, s in members)
        top = sorted(members, key=lambda ns: (-ns[1], ns[0]))[0][0]
        out.append('{}: {}, {}, {}'.format(dept, len(members), total, top))
    return '\n'.join(out)

