def transform(text):
    counters = []
    out = []
    for line in text.strip().split('\n'):
        if not line.strip():
            continue
        depth_s, _, title = line.partition('|')
        depth = int(depth_s)
        while len(counters) > depth + 1:
            counters.pop()
        if len(counters) == depth + 1:
            counters[depth] += 1
        else:
            counters.append(1)
        number = '.'.join(str(c) for c in counters) + '.'
        out.append('{} {}'.format(number, title.strip()))
    return '\n'.join(out)

