from decimal import Decimal, ROUND_HALF_UP


def transform(text):
    groups = []
    current = {"name": "(root)", "verts": 0, "faces": 0, "tri": 0, "quad": 0, "ngon": 0}
    groups.append(current)
    xs, ys, zs = [], [], []
    refs = 0
    maxindex = 0

    for raw in text.split("\n"):
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        parts = line.split()
        key = parts[0]
        if key == "o":
            current = {"name": " ".join(parts[1:]), "verts": 0, "faces": 0,
                       "tri": 0, "quad": 0, "ngon": 0}
            groups.append(current)
        elif key == "v":
            current["verts"] += 1
            xs.append(Decimal(parts[1]))
            ys.append(Decimal(parts[2]))
            zs.append(Decimal(parts[3]))
        elif key == "f":
            tokens = parts[1:]
            current["faces"] += 1
            n = len(tokens)
            if n == 3:
                current["tri"] += 1
            elif n == 4:
                current["quad"] += 1
            elif n >= 5:
                current["ngon"] += 1
            for tok in tokens:
                idx = int(tok.split("/")[0])
                refs += 1
                if idx > maxindex:
                    maxindex = idx

    def fmt(value):
        return str(Decimal(value).quantize(Decimal("0.001"), rounding=ROUND_HALF_UP))

    out = []
    for g in groups:
        if g["name"] == "(root)" and g["verts"] == 0 and g["faces"] == 0:
            continue
        out.append("name=%s verts=%d faces=%d tri=%d quad=%d ngon=%d" % (
            g["name"], g["verts"], g["faces"], g["tri"], g["quad"], g["ngon"]))
    if xs:
        out.append("min=%s/%s/%s" % (fmt(min(xs)), fmt(min(ys)), fmt(min(zs))))
        out.append("max=%s/%s/%s" % (fmt(max(xs)), fmt(max(ys)), fmt(max(zs))))
    else:
        out.append("min=none")
        out.append("max=none")
    out.append("refs=%d maxindex=%d" % (refs, maxindex))
    return "\n".join(out)

def transform(text):
    disc_title = None
    disc_performer = None
    tracks = []
    current = None

    def quoted(line):
        first = line.find('"')
        last = line.rfind('"')
        if first == -1 or last <= first:
            return line.split(None, 1)[1].strip() if " " in line else ""
        return line[first + 1:last]

    for raw in text.split("\n"):
        line = raw.strip()
        if not line:
            continue
        upper = line.upper()
        if upper.startswith("TRACK "):
            parts = line.split()
            current = {"num": parts[1], "type": parts[2] if len(parts) > 2 else "",
                       "title": None, "performer": None, "start": None}
            tracks.append(current)
        elif upper.startswith("TITLE "):
            if current is None:
                disc_title = quoted(line)
            else:
                current["title"] = quoted(line)
        elif upper.startswith("PERFORMER "):
            if current is None:
                disc_performer = quoted(line)
            else:
                current["performer"] = quoted(line)
        elif upper.startswith("INDEX "):
            parts = line.split()
            if current is not None and parts[1] == "01":
                mm, ss, ff = parts[2].split(":")
                current["start"] = (int(mm) * 60 + int(ss)) * 75 + int(ff)

    playable = [t for t in tracks if t["type"] == "AUDIO" and t["start"] is not None]
    ordered = [t for t in tracks if t["start"] is not None]

    def stamp(frames):
        minutes, rest = divmod(frames, 60 * 75)
        seconds, ff = divmod(rest, 75)
        return "%02d:%02d:%02d" % (minutes, seconds, ff)

    out = []
    total = 0
    for track in playable:
        later = [t["start"] for t in ordered if t["start"] > track["start"]]
        if later:
            duration = stamp(min(later) - track["start"])
            total += min(later) - track["start"]
        else:
            duration = "--:--:--"
        title = track["title"] or disc_title or "Unknown"
        performer = track["performer"] or disc_performer or "Unknown"
        out.append("%s|%s|%s|%s - %s" % (
            track["num"], stamp(track["start"]), duration, performer, title))
    out.append("tracks=%d playable=%s" % (len(playable), stamp(total)))
    return "\n".join(out)

from decimal import Decimal, ROUND_HALF_UP, InvalidOperation

UNITS = {"K": 1024, "M": 1024 ** 2, "G": 1024 ** 3, "T": 1024 ** 4}


def transform(text):
    skipped = []
    rows = []
    for raw in text.split("\n"):
        if not raw.strip():
            continue
        if "\t" not in raw:
            skipped.append("SKIP " + raw.strip())
            continue
        size_part, path = raw.split("\t", 1)
        size_part = size_part.strip()
        path = path.rstrip()
        suffix = size_part[-1:].upper()
        if suffix in UNITS:
            number, factor = size_part[:-1], UNITS[suffix]
        else:
            number, factor = size_part, 1
        try:
            value = Decimal(number)
        except InvalidOperation:
            skipped.append("SKIP " + raw.strip())
            continue
        total = (value * factor).quantize(Decimal("1"), rounding=ROUND_HALF_UP)
        rows.append((int(total), path))

    def human(nbytes):
        steps = [("TiB", 1024 ** 4), ("GiB", 1024 ** 3), ("MiB", 1024 ** 2), ("KiB", 1024)]
        for label, factor in steps:
            if nbytes >= factor:
                scaled = (Decimal(nbytes) / Decimal(factor)).quantize(
                    Decimal("0.01"), rounding=ROUND_HALF_UP)
                return "%s %s" % (scaled, label)
        return "%d B" % nbytes

    rows.sort(key=lambda r: (-r[0], r[1]))
    out = list(skipped)
    for nbytes, path in rows:
        out.append("%d|%s|%s" % (nbytes, path, human(nbytes)))
    out.append("entries=%d total=%d" % (len(rows), sum(r[0] for r in rows)))
    return "\n".join(out)

