        elif source.startswith("LABEL="):
            kind = "label"
        elif source.startswith("/"):
            kind = "device"
        else:
            kind = "pseudo"
        seen = []
        for opt in optfield.split(","):
            if not opt or opt == "defaults":
                continue
            if opt not in seen:
                seen.append(opt)
        options = ",".join(sorted(seen)) if seen else "defaults"
        rows.append((mount, fstype, kind, options, dump, passno))

    rows.sort(key=lambda r: (r[0], r[1]))
    out = list(invalid)
    for mount, fstype, kind, options, dump, passno in rows:
        out.append("%s|%s|%s|%s|%s%s" % (mount, fstype, kind, options, dump, passno))
    pseudo = sum(1 for r in rows if r[2] == "pseudo")
    out.append("mounts=%d invalid=%d pseudo=%d" % (len(rows), len(invalid), pseudo))
    return "\n".join(out)

from decimal import Decimal, ROUND_HALF_UP


def transform(text):
    out = []
    n = 0
    for raw in text.split("\n"):
        line = raw.strip()
        if not line:
            continue
        n += 1
        if not line.startswith("$") or line.count("*") != 1:
            out.append("%d: BADSUM" % n)
            continue
        body, _, tail = line[1:].partition("*")
        if len(tail) < 2:
            out.append("%d: BADSUM" % n)
            continue
        checksum = 0
        for ch in body:
            checksum ^= ord(ch)
        if "%02X" % checksum != tail[:2].upper():
            out.append("%d: BADSUM" % n)
            continue
        fields = body.split(",")
        if not fields[0].endswith("GGA"):
            out.append("%d: SKIP %s" % (n, fields[0]))
            continue
        if len(fields) < 10:
            out.append("%d: BADSUM" % n)
            continue
        if fields[6] == "0":
            out.append("%d: NOFIX" % n)
            continue

        def to_degrees(value, hemi, deg_digits):
            deg = Decimal(value[:deg_digits])
            minutes = Decimal(value[deg_digits:])
            result = deg + minutes / Decimal(60)
            if hemi in ("S", "W"):
                result = -result
            return str(result.quantize(Decimal("0.000001"), rounding=ROUND_HALF_UP))

        utc = fields[1].split(".")[0]
        stamp = "%s:%s:%s" % (utc[0:2], utc[2:4], utc[4:6])
        lat = to_degrees(fields[2], fields[3], 2)
        lon = to_degrees(fields[4], fields[5], 3)
        out.append("%d: %s %s %s sats=%d alt=%sm" % (
            n, stamp, lat, lon, int(fields[7]), fields[9]))
    return "\n".join(out)

def transform(text):
    origin = "."
    default_ttl = "3600"
    last_owner = None
    records = []

    for raw in text.split("\n"):
        line = raw.split(";")[0].rstrip()
        if not line.strip():
            continue
        if line.lstrip().startswith("$"):
            parts = line.split()
            if parts[0].upper() == "$ORIGIN":
                origin = parts[1]
            elif parts[0].upper() == "$TTL":
                default_ttl = parts[1]
            continue

        indented = line[0].isspace()
        tokens = line.split()
        if indented:
            owner_token = last_owner
        else:
            owner_token = tokens[0]
            tokens = tokens[1:]
        last_owner = owner_token

        ttl = default_ttl
        if tokens and tokens[0].isdigit():
            ttl = tokens[0]
            tokens = tokens[1:]
        if tokens and tokens[0].upper() == "IN":
            tokens = tokens[1:]
        rtype = tokens[0].upper()
        rdata = " ".join(tokens[1:])

        def expand(name):
            if name == "@":
                return origin
            if name.endswith("."):
                return name
            return name + "." + origin

        owner = expand(owner_token)
        if rtype in ("NS", "CNAME", "PTR"):
            rdata = expand(rdata)
        elif rtype == "MX":
            pref, target = rdata.split(None, 1)
            rdata = pref + " " + expand(target)
        records.append((owner, ttl, rtype, rdata))

    records.sort(key=lambda r: (r[0], r[2], r[3]))
    out = ["%s %s %s %s" % r for r in records]
    types = sorted({r[2] for r in records})
    out.append("records=%d types=%s" % (len(records), ",".join(types)))
    return "\n".join(out)

def transform(text):
    raw_lines = text.split("\n")
    unfolded = []
    for line in raw_lines:
        if line[:1] in (" ", "\t") and unfolded:
            unfolded[-1] += line[1:]
        else:
            unfolded.append(line)

    def unescape(value):
        out = []
        i = 0
        while i < len(value):
            ch = value[i]
            if ch == "\\" and i + 1 < len(value):
                nxt = value[i + 1]
                if nxt in ("n", "N"):
                    out.append(" / ")
                elif nxt == ",":
                    out.append(",")
                elif nxt == ";":
                    out.append(";")
                else:
                    out.append(nxt)
                i += 2
                continue
            out.append(ch)
            i += 1
        return "".join(out)

    contacts = []
    card = None
    for line in unfolded:
        stripped = line.strip()
        if not stripped:
            continue
        if stripped.upper() == "BEGIN:VCARD":
            card = {"fn": None, "n": None, "org": None, "emails": [], "tels": []}
            continue
        if stripped.upper() == "END:VCARD":
            if card is not None:
                contacts.append(card)
            card = None
            continue
        if card is None or ":" not in stripped:
            continue
        head, _, value = stripped.partition(":")
        prop = head.split(";")[0].upper()
        value = unescape(value)
        if prop == "FN" and card["fn"] is None:
            card["fn"] = value
        elif prop == "N" and card["n"] is None:
            card["n"] = value
        elif prop == "ORG" and card["org"] is None:
            card["org"] = " / ".join(part.strip() for part in value.split(";") if part.strip())
        elif prop == "EMAIL":
            card["emails"].append(value)
        elif prop == "TEL":
            cleaned = value
            for junk in (" ", "-", ".", "(", ")"):
                cleaned = cleaned.replace(junk, "")
            card["tels"].append(cleaned)

    out = []
    with_email = 0
    for card in contacts:
        name = card["fn"]
        if not name:
            if card["n"]:
                parts = card["n"].split(";")
                given = parts[1] if len(parts) > 1 else ""
                family = parts[0] if parts else ""
                name = (given + " " + family).strip()
            if not name:
                name = "Unnamed"
        org = card["org"] or "-"
        emails = ",".join(card["emails"]) if card["emails"] else "-"
        tels = ",".join(card["tels"]) if card["tels"] else "-"
        if card["emails"]:
            with_email += 1
        out.append("%s|%s|%s|%s" % (name, org, emails, tels))
    out.append("contacts=%d withemail=%d" % (len(contacts), with_email))
    return "\n".join(out)

def transform(text):
    name = "Untitled"
    entries = []
    pending = None
    for raw in text.split("\n"):
        line = raw.strip()
        if not line:
            continue
        if line.startswith("#"):
            if line.startswith("#PLAYLIST:"):
                name = line[len("#PLAYLIST:"):].strip()
            elif line.startswith("#EXTINF:"):
                info = line[len("#EXTINF:"):]
                secs, _, title = info.partition(",")
                pending = (int(secs.strip()), title)
            continue
        if pending is not None:
            entries.append((pending[0], pending[1], line))
            pending = None

    out = []
    known_total = 0
    known = 0
    for index, (secs, title, uri) in enumerate(entries, start=1):
        if " - " in title:
            artist, song = title.split(" - ", 1)
            artist, song = artist.strip(), song.strip()
        else:
            artist, song = "<unknown>", title.strip()
        if uri.startswith("http://") or uri.startswith("https://"):
            medium = "stream"
        else:
            tail = uri.split("/")[-1]
            medium = tail.rsplit(".", 1)[1].lower() if "." in tail else "none"
        if secs == -1:
            length = "--:--"
        else:
            length = "%d:%02d" % (secs // 60, secs % 60)
            known_total += secs
            known += 1
        out.append("%d. %s | %s | %s | %s" % (index, artist, song, length, medium))
    hours, rest = divmod(known_total, 3600)
    out.append("playlist=%s entries=%d known=%d total=%d:%02d:%02d" % (
        name, len(entries), known, hours, rest // 60, rest % 60))
    return "\n".join(out)

import re
from decimal import Decimal, ROUND_HALF_UP

WIND = re.compile(r"^(\d{3}|VRB)(\d{2,3})(?:G(\d{2,3}))?KT$")
TEMP = re.compile(r"^(M?\d{1,2})/(M?\d{1,2})$")


def transform(text):
    out = []
    good = 0
    bad = 0
    for raw in text.split("\n"):
        line = raw.strip()
        if not line:
            continue
        tokens = line.split()
        if len(tokens) < 2 or len(tokens[1]) != 7 or not tokens[1].endswith("Z") \
                or not tokens[1][:6].isdigit():
            out.append("%s INVALID" % tokens[0])
            bad += 1
            continue
        station = tokens[0]
        stamp = tokens[1]
        wind = vis = temp = dew = qnh = "?"
        for token in tokens[2:]:
            if wind == "?" and token.endswith("KT"):
                m = WIND.match(token)
                if m:
                    direction, speed, gust = m.groups()
                    if direction == "000" and speed == "00":
                        wind = "calm"
                    else:
                        wind = "%s@%skt" % (direction, speed)
                        if gust:
                            wind += "g%s" % gust
                    continue
            if vis == "?":
                if token == "CAVOK":
                    vis = "CAVOK"
                    continue
                if token == "9999":
                    vis = "10+km"
                    continue
                if len(token) == 4 and token.isdigit():
                    metres = (Decimal(token) / Decimal(1000)).quantize(
                        Decimal("0.1"), rounding=ROUND_HALF_UP)
                    vis = "%skm" % metres
                    continue
                if token.endswith("SM"):
                    body = token[:-2]
                    if "/" in body:
                        num, den = body.split("/")
                        miles = Decimal(num) / Decimal(den)
                    else:
                        miles = Decimal(body)
                    km = (miles * Decimal("1.609344")).quantize(
                        Decimal("0.1"), rounding=ROUND_HALF_UP)
                    vis = "%skm" % km
                    continue
            if temp == "?":
                m = TEMP.match(token)
                if m:
                    def celsius(value):
                        sign = "-" if value.startswith("M") else ""
                        return sign + str(int(value.lstrip("M")))
                    temp = celsius(m.group(1))
                    dew = celsius(m.group(2))
                    continue
            if qnh == "?" and len(token) == 5:
                if token[0] == "Q" and token[1:].isdigit():
                    qnh = "%dhPa" % int(token[1:])
                    continue
                if token[0] == "A" and token[1:].isdigit():
                    inhg = Decimal(token[1:]) / Decimal(100)
                    hpa = (inhg * Decimal("33.8639")).quantize(
                        Decimal("0.1"), rounding=ROUND_HALF_UP)
                    qnh = "%shPa" % hpa
                    continue
        out.append("%s %s/%s:%sZ wind=%s vis=%s t=%sC dp=%sC qnh=%s" % (
            station, stamp[0:2], stamp[2:4], stamp[4:6], wind, vis, temp, dew, qnh))
        good += 1
    out.append("reports=%d invalid=%d" % (good, bad))
    return "\n".join(out)

import json


def transform(text):
    physical = text.split("\n")
    logical = []
    buffer = ""
    continuing = False
    for line in physical:
        current = line.lstrip() if continuing else line
        trailing = len(current) - len(current.rstrip("\\"))
        if trailing % 2 == 1:
            buffer += current[:-1]
            continuing = True
            continue
        buffer += current
        logical.append(buffer)
        buffer = ""
        continuing = False
    if continuing or buffer:
        logical.append(buffer)

    def unescape(chunk):
        out = []
        i = 0
        while i < len(chunk):
            ch = chunk[i]
            if ch != "\\":
                out.append(ch)
                i += 1
                continue
            if i + 1 >= len(chunk):
                i += 1
                continue
            nxt = chunk[i + 1]
            if nxt == "t":
                out.append("\t")
            elif nxt == "n":
                out.append("\n")
            elif nxt == "r":
                out.append("\r")
            elif nxt == "f":
                out.append("\f")
            elif nxt == "u":
                out.append(chr(int(chunk[i + 2:i + 6], 16)))
                i += 6
                continue
            else:
                out.append(nxt)
            i += 2
        return "".join(out)

    result = {}
    for line in logical:
        line = line.lstrip()
        if not line or line[0] in ("#", "!"):
            continue
        i = 0
        key_chars = []
        sep_index = None
        while i < len(line):
            ch = line[i]
            if ch == "\\" and i + 1 < len(line):
                key_chars.append(ch)
                key_chars.append(line[i + 1])
                i += 2
                continue
            if ch in ("=", ":") or ch.isspace():
                sep_index = i
                break
            key_chars.append(ch)
            i += 1
        raw_key = "".join(key_chars)
        if sep_index is None:
            result[unescape(raw_key)] = ""
            continue
        rest = line[sep_index:]
        stripped = rest.lstrip()
        if rest[0].isspace() and stripped[:1] in ("=", ":"):
            rest = stripped[1:]
        elif rest[0] in ("=", ":"):
            rest = rest[1:]
        else:
            rest = stripped
        value = rest.lstrip()
        result[unescape(raw_key)] = unescape(value)

    return json.dumps(result, indent=2, sort_keys=True, ensure_ascii=False)

def transform(text):
    physical = text.split("\n")
    logical = []
    buffer = None
    for line in physical:
        piece = line
        if buffer is not None:
            piece = piece.lstrip()
            piece = buffer + " " + piece
            buffer = None
        if piece.endswith("\\"):
            buffer = piece[:-1].rstrip()
            continue
        logical.append(piece)
    if buffer is not None:
        logical.append(buffer)

    targets = {}
    order = []
    phony = set()
    current = []
    for line in logical:
        if line.startswith("\t"):
            for name in current:
                targets[name]["recipes"] += 1
            continue
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        colon = stripped.find(":")
        equals = stripped.find("=")
        if equals != -1 and (colon == -1 or equals < colon):
            current = []
            continue
        if colon == -1:
            current = []
            continue
        head = stripped[:colon]
        rest = stripped[colon + 1:]
        recipe_inline = 0
        if ";" in rest:
            rest, _, _tail = rest.partition(";")
            recipe_inline = 1
        prereqs = rest.split()
        names = head.split()
        if names == [".PHONY"]:
            phony.update(prereqs)
            current = []
            continue
        current = []
        for name in names:
            if name not in targets:
                targets[name] = {"prereqs": [], "recipes": 0}
                order.append(name)
            for p in prereqs:
                if p not in targets[name]["prereqs"]:
                    targets[name]["prereqs"].append(p)
            targets[name]["recipes"] += recipe_inline
            current.append(name)

    out = []
    for name in sorted(targets):
        info = targets[name]
        prereqs = ",".join(info["prereqs"]) if info["prereqs"] else "-"
        out.append("%s: %s recipes=%d phony=%s" % (
            name, prereqs, info["recipes"], "yes" if name in phony else "no"))
    missing = sorted({p for info in targets.values() for p in info["prereqs"]
                      if p not in targets})
    out.append("missing=%s" % (",".join(missing) if missing else "-"))
    return "\n".join(out)

import re

PATTERN = re.compile(r"^P(?:(\d+)W|(?:(\d+)D)?(?:T(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?)?)$")


def transform(text):
    out = []
    ok = 0
    total_sum = 0
    for raw in text.split("\n"):
        line = raw.strip()
        if not line:
            continue
        negative = line.startswith("-")
        body = line[1:] if negative else line
        if not body.startswith("P"):
            out.append("%s -> INVALID" % line)
            continue
        rest = body[1:]
        date_part, sep, time_part = rest.partition("T")
        if "Y" in date_part or "M" in date_part or "." in body or "," in body:
            out.append("%s -> UNSUPPORTED" % line)
            continue
        if rest == "" or (sep and time_part == ""):
            out.append("%s -> INVALID" % line)
            continue
        match = PATTERN.match(body)
        if not match:
            out.append("%s -> INVALID" % line)
            continue
        weeks, days, hours, minutes, seconds = match.groups()
        total = 0
        if weeks is not None:
            total = int(weeks) * 7 * 86400
        else:
            total += int(days or 0) * 86400
            total += int(hours or 0) * 3600
            total += int(minutes or 0) * 60
            total += int(seconds or 0)
        if negative:
            total = -total

        magnitude = abs(total)
        d, rem = divmod(magnitude, 86400)
        h, rem = divmod(rem, 3600)
        m, s = divmod(rem, 60)
        if magnitude == 0:
            canonical = "PT0S"
        else:
            canonical = "P"
            if d:
                canonical += "%dD" % d
            if h or m or s:
                canonical += "T"
                if h:
                    canonical += "%dH" % h
                if m:
                    canonical += "%dM" % m
                if s:
                    canonical += "%dS" % s
        if total < 0:
            canonical = "-" + canonical
        out.append("%s -> %d -> %s" % (line, total, canonical))
        ok += 1
        total_sum += total
    out.append("ok=%d sum=%d" % (ok, total_sum))
    return "\n".join(out)

import re


def transform(text):
    entries = []
    i = 0
    while True:
        at = text.find("@", i)
        if at == -1:
            break
        brace = text.find("{", at)
        if brace == -1:
            break
        etype = text[at + 1:brace].strip().lower()
        depth = 0
        end = brace
        for pos in range(brace, len(text)):
            if text[pos] == "{":
                depth += 1
            elif text[pos] == "}":
                depth -= 1
                if depth == 0:
                    end = pos
                    break
        inner = text[brace + 1:end]
        i = end + 1
        key, _, rest = inner.partition(",")
        fields = {}
        depth = 0
        chunk = []
        chunks = []
        for ch in rest:
            if ch == "{":
                depth += 1
            elif ch == "}":
                depth -= 1
            if ch == "," and depth == 0:
                chunks.append("".join(chunk))
                chunk = []
                continue
            chunk.append(ch)
        chunks.append("".join(chunk))
        for piece in chunks:
            if "=" not in piece:
                continue
            name, _, value = piece.partition("=")
            name = name.strip().lower()
            value = value.strip()
            if value.startswith("{") and value.endswith("}"):
                value = value[1:-1]
            value = re.sub(r"\s+", " ", value).strip().replace("{", "").replace("}", "")
            fields[name] = value
        entries.append((key.strip(), etype, fields))

    def authors_of(fields):
        raw = fields.get("author")
        if not raw:
            return "Anonymous"
        formatted = []
        for person in raw.split(" and "):
            words = person.split()
            if not words:
                continue
            surname = words[-1]
            initials = " ".join(w[0] + "." for w in words[:-1])
            formatted.append("%s, %s" % (surname, initials) if initials else surname)
        return " & ".join(formatted) if formatted else "Anonymous"

    out = []
    for key, etype, fields in sorted(entries, key=lambda e: e[0]):
        year = fields.get("year", "n.d.")
        title = fields.get("title", "Untitled")
        who = authors_of(fields)
        pages = fields.get("pages", "").replace("--", "-")
        if etype == "article":
            tail = fields.get("journal", "")
            volume = fields.get("volume", "")
            number = fields.get("number", "")
            piece = tail
            if volume:
                piece += ", " + volume
                if number:
                    piece += "(%s)" % number
            if pages:
                piece += ", " + pages
            citation = "%s (%s). %s. %s." % (who, year, title, piece)
        elif etype == "book":
            citation = "%s (%s). %s. %s." % (who, year, title, fields.get("publisher", ""))
        else:
            citation = "%s (%s). %s." % (who, year, title)
        out.append("%s: %s" % (key, citation))
    types = sorted({e[1] for e in entries})
    out.append("entries=%d types=%s" % (len(entries), ",".join(types)))
    return "\n".join(out)

