import re
from fractions import Fraction

MIXED = re.compile(r"^(\d+)\s+(\d+)/(\d+)\s+(.*)$")
FRACTION = re.compile(r"^(\d+)/(\d+)\s+(.*)$")
DECIMAL = re.compile(r"^(\d+\.\d+|\d+)\s+(.*)$")


def transform(text):
    lines = [ln for ln in text.split("\n") if ln.strip()]
    factor = Fraction(1)
    body = []
    for index, line in enumerate(lines):
        stripped = line.strip()
        if index == 0 and stripped.lower().startswith("scale:"):
            raw = stripped.split(":", 1)[1].strip()
            factor = Fraction(raw) if "/" in raw else Fraction(raw)
            continue
        body.append(stripped)

    def render(value):
        if value.denominator == 1:
            return str(value.numerator)
        whole = value.numerator // value.denominator
        remainder = value - whole
        if whole == 0:
            return "%d/%d" % (remainder.numerator, remainder.denominator)
        return "%d %d/%d" % (whole, remainder.numerator, remainder.denominator)

    out = []
    scaled = 0
    passthrough = 0
    for line in body:
        m = MIXED.match(line)
        if m:
            qty = Fraction(int(m.group(1))) + Fraction(int(m.group(2)), int(m.group(3)))
            rest = m.group(4)
        else:
            m = FRACTION.match(line)
            if m:
                qty = Fraction(int(m.group(1)), int(m.group(2)))
                rest = m.group(3)
            else:
                m = DECIMAL.match(line)
                if m:
                    qty = Fraction(m.group(1))
                    rest = m.group(2)
                else:
                    qty = None
        if qty is None:
            out.append(line)
            passthrough += 1
            continue
        out.append("%s %s" % (render(qty * factor), rest))
        scaled += 1
    out.append("scaled=%d passthrough=%d" % (scaled, passthrough))
    return "\n".join(out)

import re

PLAN = re.compile(r"^1\.\.(\d+)$")
TEST = re.compile(r"^(not ok|ok)\b\s*(\d+)?\s*(.*)$")


def transform(text):
    plan = None
    tests = []
    for raw in text.split("\n"):
        if not raw.strip():
            continue
        if raw[0].isspace():
            continue
        line = raw.strip()
        if line.lower().startswith("tap version"):
            continue
        if line.startswith("#"):
            continue
        m = PLAN.match(line)
        if m:
            plan = int(m.group(1))
            continue
        m = TEST.match(line)
        if not m:
            continue
        status, _number, rest = m.groups()
        directive = None
        reason = ""
        if "#" in rest:
            body, _, tail = rest.partition("#")
            tail = tail.strip()
            keyword, _, remainder = tail.partition(" ")
            if keyword.upper() in ("SKIP", "TODO"):
                directive = keyword.upper()
                reason = remainder.strip()
                rest = body
        description = rest.strip()
        if description.startswith("- "):
            description = description[2:].strip()
        if directive == "SKIP":
            kind = "skip"
        elif directive == "TODO":
            kind = "todo"
        elif status == "ok":
            kind = "pass"
        else:
            kind = "fail"
        tests.append((kind, description, reason))

    out = []
    for position, (kind, description, _reason) in enumerate(tests, start=1):
        if kind == "fail":
            out.append("FAIL %d %s" % (position, description))
    for position, (kind, description, reason) in enumerate(tests, start=1):
        if kind == "skip":
            out.append("SKIP %d %s (%s)" % (position, description, reason or "no reason"))

    counts = {"pass": 0, "fail": 0, "skip": 0, "todo": 0}
    for kind, _d, _r in tests:
        counts[kind] += 1
    out.append("plan=%s ran=%d pass=%d fail=%d skip=%d todo=%d" % (
        plan if plan is not None else "?", len(tests),
        counts["pass"], counts["fail"], counts["skip"], counts["todo"]))
    good = counts["fail"] == 0 and (plan is None or plan == len(tests))
    out.append("result=%s" % ("PASS" if good else "FAIL"))
    return "\n".join(out)

