def transform(text):
    sections = {}
    order = []
    current = None
    for line in text.strip('\n').split('\n'):
        line = line.strip()
        if not line:
            continue
        if line.startswith('[') and line.endswith(']'):
            current = line[1:-1]
            sections[current] = {}
            order.append(current)
        elif '=' in line and current:
            key, val = line.split('=', 1)
            sections[current][key.strip()] = parse_value(val)

    resolved = {}

    def resolve(name):
        if name in resolved:
            return resolved[name]
        raw = dict(sections[name])
        parent_name = raw.pop('extends', None)
        if parent_name:
            merged = dict(resolve(parent_name))
            merged.update(raw)
        else:
            merged = raw
        resolved[name] = merged
        return merged

    output = {name: resolve(name) for name in order}
    return json.dumps(output, indent=2, ensure_ascii=False)

