def parse_duration(s):
    pattern = re.findall(r'(\d+)([hms])', s)
    total = 0
    for value, unit in pattern:
        value = int(value)
        if unit == 'h':
            total += value * 3600
        elif unit == 'm':
            total += value * 60
        elif unit == 's':
            total += value
    return total

def transform(text):
    lines = [l for l in text.strip('\n').split('\n') if l.strip()]
    totals = {}
    for line in lines:
        task, dur = line.split(':', 1)
        totals[task] = totals.get(task, 0) + parse_duration(dur)
    return json.dumps(totals, indent=2, ensure_ascii=False)

import json

SCALE = {
    'Strongly Disagree': 1,
    'Disagree': 2,
    'Neutral': 3,
    'Agree': 4,
    'Strongly Agree': 5
}

def transform(text):
    lines = [l for l in text.strip('\n').split('\n') if l.strip()]
    header = lines[0].split(',')
    questions = header[1:]
    sums = {q: 0 for q in questions}
    count = 0
    responses = []
    for line in lines[1:]:
        cols = line.split(',')
        respondent = cols[0]
        answers = cols[1:]
        numeric = {questions[i]: SCALE[answers[i]] for i in range(len(questions))}
        responses.append({'respondent': respondent, 'scores': numeric})
        for q in questions:
            sums[q] += numeric[q]
        count += 1
    averages = {q: round(sums[q] / count, 2) for q in questions}
    result = {'responses': responses, 'averages': averages}
    return json.dumps(result, indent=2, ensure_ascii=False)

