from collections import Counter

STOPWORDS = {'the', 'a', 'an', 'at', 'but', 'over', 'is', 'in', 'on', 'and', 'to', 'of'}

def transform(text):
    words = re.findall(r"[a-zA-Z']+", text.lower())
    words = [w for w in words if w not in STOPWORDS]
    counts = Counter(words)
    result = sorted(counts.items(), key=lambda x: (-x[1], x[0]))
    return json.dumps(result, indent=2, ensure_ascii=False)

import json

def transform(text):
    lines = [l for l in text.strip('\n').split('\n') if l.strip()]
    result = {}
    current_id = None
    seq = ''

    def flush():
        if current_id:
            gc = seq.count('G') + seq.count('C')
            pct = round(gc / len(seq) * 100, 2) if seq else 0
            result[current_id] = pct

    for line in lines:
        if line.startswith('>'):
            flush()
            current_id = line[1:].strip()
            seq = ''
        else:
            seq += line.strip()
    flush()
    return json.dumps(result, indent=2, ensure_ascii=False)

