import json

def transform(text):
    result = {}
    section = None
    for line in text.strip().split('\n'):
        line = line.strip()
        if not line or line.startswith('#'):
            continue
        if line.startswith('[') and line.endswith(']'):
            section = line[1:-1]
            result[section] = {}
        elif '=' in line and section:
            k, v = line.split('=', 1)
            result[section][k.strip()] = v.strip()
    return json.dumps(result)

