import csv, io, json

def transform(text):
    reader = csv.DictReader(io.StringIO(text.strip()))
    credits = debits = 0.0
    for row in reader:
        amt = float(row['amount'])
        if amt >= 0:
            credits += amt
        else:
            debits += amt
    return json.dumps({
        "total_credits": round(credits, 2),
        "total_debits": round(debits, 2),
        "net_balance": round(credits + debits, 2)
    })

